"""Maintainer-only generator for the committed issue #174 as-of fixtures.

Regenerates the two committed artifacts byte-for-byte from the contract's
fixed literals (issue #174 Fixtures section):

- ``expiry-input.jsonl`` (SHA-256 160db65a118bfd72b93c756722e03e81fb3f8caee
  acbcafe208a93be4533a20e): three ``state`` records for namespace
  ``fixture:expiry-174`` — ids ...0001..0003, contents expiry-row-{1,2,3},
  classes endpoint/metric/setting, inject_until 2026-09-10T00:00:00Z /
  2026-09-09T23:59:59Z / 2026-09-10T00:00:01Z — serialized as compact
  sorted-key JSON, LF BETWEEN records, NO trailing LF.
- ``expiry-golden.json`` (SHA-256 a2218a14e0ea53e645afb59f32b4167b9a4ed09b4
  4d699cad07d6da575cd56d0): the canonical ``recall --as-of
  2026-09-10T00:00:00Z`` projection — a bare JSON list of
  {content,id,namespace} sorted by id, json.dumps sort_keys indent 2, NO
  trailing LF.

Default invocation VERIFIES: with the committed files present the script
regenerates into memory and byte-compares, refusing to overwrite a committed
file whose bytes would drift (exit 1) — only a missing file is written.
``--out-dir DIR`` always writes both files into DIR (the scratch-regeneration
mode tests use). Digests print lowercase on success.

Run from the repo root:  python tests/fixtures/asof/make_fixtures.py
"""

from __future__ import annotations

import argparse
import hashlib
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent

NAMESPACE = "fixture:expiry-174"
SEED_TS = "2026-09-10T00:00:00Z"

# The contract's fixed seed (order = id order). Boundary law:
# inject_until <= now is EXPIRED (inclusive).
ROWS = (
    ("00000000-0000-4000-8000-000000000001", "expiry-row-1", "endpoint",
     "2026-09-10T00:00:00Z"),
    ("00000000-0000-4000-8000-000000000002", "expiry-row-2", "metric",
     "2026-09-09T23:59:59Z"),
    ("00000000-0000-4000-8000-000000000003", "expiry-row-3", "setting",
     "2026-09-10T00:00:01Z"),
)

INPUT_DIGEST = ("160db65a118bfd72b93c756722e03e81fb3f8cae"
                "eacbcafe208a93be4533a20e")
GOLDEN_DIGEST = ("a2218a14e0ea53e645afb59f32b4167b9a4ed09b4"
                 "4d699cad07d6da575cd56d0")


def expiry_input_bytes() -> bytes:
    """Compact sorted-key JSONL: LF between records, NO trailing LF."""
    records = [
        {
            "confidence": 0.9,
            "content": content,
            "expiry_class": expiry_class,
            "id": mid,
            "ingestion_ts": SEED_TS,
            "inject_until": inject_until,
            "namespace": NAMESPACE,
            "signal": "grounded",
            "source_ref": NAMESPACE,
            "tags": "",
            "type": "state",
            "valid_from": SEED_TS,
        }
        for mid, content, expiry_class, inject_until in ROWS
    ]
    return "\n".join(
        json.dumps(rec, sort_keys=True, separators=(",", ":"))
        for rec in records).encode("utf-8")


def expiry_golden_bytes() -> bytes:
    """The canonical as-of projection: bare list sorted by id, sort_keys
    indent 2, NO trailing LF."""
    projection = [
        {"content": content, "id": mid, "namespace": NAMESPACE}
        for mid, content, _cls, _until in sorted(ROWS)
    ]
    return json.dumps(projection, sort_keys=True, indent=2).encode("utf-8")


def _digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument(
        "--out-dir", type=Path, default=None,
        help="always write both fixtures into this directory (scratch "
             "regeneration); default verifies the committed bytes and "
             "refuses to overwrite on drift")
    out_dir = ap.parse_args().out_dir

    artifacts = (
        ("expiry-input.jsonl", expiry_input_bytes(), INPUT_DIGEST),
        ("expiry-golden.json", expiry_golden_bytes(), GOLDEN_DIGEST),
    )
    failed = False
    for name, data, pinned in artifacts:
        digest = _digest(data)
        if digest != pinned:
            # The generator itself drifted from the contract's pinned bytes.
            print(f"ERROR: generated {name} digest {digest} != pinned "
                  f"{pinned}", file=sys.stderr)
            failed = True
            continue
        target = (out_dir / name) if out_dir is not None else (HERE / name)
        if out_dir is None and target.exists():
            committed = target.read_bytes()
            if committed != data:
                print(
                    f"ERROR: committed {target} differs from the "
                    f"regenerated bytes (committed sha256 {_digest(committed)}"
                    f", regenerated sha256 {digest}); refusing to overwrite — "
                    f"regenerate deliberately into a scratch dir with "
                    f"--out-dir and commit the pair together",
                    file=sys.stderr)
                failed = True
                continue
            print(f"verified {target} (sha256 {digest})")
        else:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data)
            print(f"wrote {target} (sha256 {digest})")
    if failed:
        return 1
    print()
    print("verify the committed bytes with:")
    print("  sha256sum tests/fixtures/asof/expiry-input.jsonl")
    print("  sha256sum tests/fixtures/asof/expiry-golden.json")
    return 0


if __name__ == "__main__":
    sys.exit(main())
